package de.cocoa.discorddeck;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.net.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
 final Handler ui=new Handler(Looper.getMainLooper());
 final ScheduledExecutorService poll=Executors.newSingleThreadScheduledExecutor();
 final ThreadPoolExecutor commands=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(16));
 final Map<String,Server> servers=new LinkedHashMap<>();
 final Button[] pads=new Button[100];final SeekBar[] gains=new SeekBar[100];final TextView[] gainLabels=new TextView[100];final boolean[] adjusting=new boolean[100];
 TextView state;Spinner computers;Button pair;EditText manual;SharedPreferences prefs;
 volatile Server selected;volatile String key="",pairedId="";ScheduledFuture<?> polling;int ticks;
 record Server(String id,String name,String host,int port){public String toString(){return name;}}
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 static final int BG=0xFF0D141A,CARD=0xFF141C23,STROKE=0xFF26313A,GREEN=0xFFA8E28C,TEXT=0xFFF1F4F6,MUTED=0xFF8B97A1,RED=0xFFF0605A;
 android.graphics.drawable.GradientDrawable shape(int fill,int stroke,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(fill);if(stroke!=0)d.setStroke(dp(1),stroke);d.setCornerRadius(dp(radius));return d;}
 android.graphics.drawable.Drawable ripple(android.graphics.drawable.Drawable base){return new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x40A8E28C),base,null);}
 Button action(String text,int fill,int stroke,int color){Button b=new Button(this);b.setText(text);b.setAllCaps(false);b.setTextSize(14);b.setTextColor(color);b.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));b.setBackgroundTintList(null);b.setBackground(ripple(shape(fill,stroke,12)));b.setStateListAnimator(null);return b;}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);prefs=getSharedPreferences("remote",0);key=prefs.getString("key","");pairedId=prefs.getString("id","");
  getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);
  LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(10),dp(12),0);root.setBackgroundColor(BG);
  root.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(12),insets.getSystemWindowInsetTop()+dp(8),dp(12),insets.getSystemWindowInsetBottom());return insets;});
  LinearLayout header=new LinearLayout(this);header.setOrientation(0);header.setGravity(Gravity.CENTER_VERTICAL);header.setPadding(dp(2),dp(6),0,dp(10));
  ImageView fish=new ImageView(this);fish.setImageResource(R.drawable.sardine);fish.setScaleType(ImageView.ScaleType.FIT_CENTER);fish.setContentDescription("Sardine");header.addView(fish,new LinearLayout.LayoutParams(dp(96),dp(48)));
  LinearLayout names=new LinearLayout(this);names.setOrientation(1);names.setPadding(dp(10),0,0,0);
  TextView title=new TextView(this);title.setText("Sardinöööses");title.setTextColor(TEXT);title.setTextSize(26);title.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));names.addView(title);
  TextView sub=new TextView(this);sub.setText("DISCORD DECK");sub.setTextColor(MUTED);sub.setTextSize(11);sub.setLetterSpacing(.18f);names.addView(sub);
  header.addView(names);root.addView(header);
  state=new TextView(this);state.setText("PC wird im lokalen Netz gesucht …");state.setTextColor(MUTED);state.setTextSize(13);state.setPadding(dp(4),0,0,dp(6));root.addView(state);
  computers=new Spinner(this);computers.setBackground(shape(CARD,STROKE,12));computers.setPopupBackgroundDrawable(shape(CARD,STROKE,12));computers.setPadding(dp(10),0,dp(10),0);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,dp(44));sp.setMargins(0,0,0,dp(8));root.addView(computers,sp);computers.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){}public void onItemSelected(AdapterView<?> a,View v,int pos,long id){if(v instanceof TextView t)t.setTextColor(TEXT);Object item=a.getItemAtPosition(pos);if(item instanceof Server s){selected=s;pair.setVisibility(!s.id.equals(pairedId)?View.VISIBLE:View.GONE);}}});
  LinearLayout actions=new LinearLayout(this);pair=action("Mit PC koppeln",CARD,GREEN,GREEN);pair.setOnClickListener(v->pairDialog());LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(0,dp(48),1);ap.setMargins(0,0,dp(6),0);actions.addView(pair,ap);Button stop=action("■  Alle Sounds stoppen",RED,0,Color.WHITE);stop.setOnClickListener(v->command("/stop"));actions.addView(stop,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams acp=new LinearLayout.LayoutParams(-1,-2);acp.setMargins(0,0,0,dp(8));root.addView(actions,acp);
  LinearLayout fallback=new LinearLayout(this);manual=new EditText(this);manual.setSingleLine();manual.setHint("PC-IP, falls Suche nichts findet");manual.setTextColor(TEXT);manual.setHintTextColor(MUTED);manual.setTextSize(12);manual.setBackground(shape(CARD,STROKE,12));manual.setPadding(dp(12),0,dp(12),0);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(0,dp(44),1);mp.setMargins(0,0,dp(6),0);fallback.addView(manual,mp);Button find=action("Suchen",CARD,STROKE,TEXT);find.setOnClickListener(v->{String host=manual.getText().toString().trim();if(!host.matches("[0-9.]{7,15}")){message("IPv4-Adresse eingeben");return;}submit(()->{try{Server s=identify(host,47836);found(s);}catch(Exception e){message("PC nicht erreichbar");}});});fallback.addView(find,new LinearLayout.LayoutParams(dp(96),dp(44)));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.setMargins(0,0,0,dp(8));root.addView(fallback,fp);
  ScrollView scroll=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);
  for(int row=0;row<20;row++){LinearLayout line=new LinearLayout(this);for(int col=0;col<5;col++){int slot=row*5+col;Button b=new Button(this);b.setText(label(slot,"Frei"));b.setTextSize(11);b.setMaxLines(4);b.setEllipsize(android.text.TextUtils.TruncateAt.END);b.setTextColor(TEXT);b.setBackgroundTintList(null);b.setBackground(ripple(shape(CARD,STROKE,14)));b.setStateListAnimator(null);b.setAllCaps(false);b.setPadding(dp(3),dp(3),dp(3),dp(3));b.setEnabled(false);b.setContentDescription("Sound "+(slot+1));b.setOnClickListener(v->command("/play/"+(slot+1)));pads[slot]=b;LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(148),1);p.setMargins(dp(2),dp(2),dp(2),dp(2));LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);cell.addView(b,new LinearLayout.LayoutParams(-1,dp(88)));TextView level=new TextView(this);level.setText("65 %");level.setTextSize(10);level.setTextColor(MUTED);level.setGravity(Gravity.CENTER);gainLabels[slot]=level;cell.addView(level);SeekBar gain=new SeekBar(this);gain.setMax(400);gain.setProgress(65);gain.setEnabled(false);gain.setProgressTintList(android.content.res.ColorStateList.valueOf(GREEN));gain.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(STROKE));gain.setThumbTintList(android.content.res.ColorStateList.valueOf(Color.WHITE));gain.setPadding(dp(5),0,dp(5),0);gain.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar bar){adjusting[slot]=true;}public void onProgressChanged(SeekBar bar,int value,boolean user){level.setText(value+" %");}public void onStopTrackingTouch(SeekBar bar){command("/gain/"+(slot+1)+"/"+bar.getProgress());adjusting[slot]=false;}});gains[slot]=gain;cell.addView(gain,new LinearLayout.LayoutParams(-1,dp(40)));line.addView(cell,p);}rows.addView(line);}scroll.addView(rows);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);
 }
 CharSequence label(int slot,String name){String n=String.format(java.util.Locale.ROOT,"%02d",slot+1);android.text.SpannableString s=new android.text.SpannableString(n+"\n"+name);s.setSpan(new android.text.style.ForegroundColorSpan(MUTED),0,n.length(),0);s.setSpan(new android.text.style.RelativeSizeSpan(.85f),0,n.length(),0);return s;}
 @Override protected void onStart(){super.onStart();polling=poll.scheduleWithFixedDelay(this::tick,0,2,TimeUnit.SECONDS);}
 @Override protected void onStop(){if(polling!=null)polling.cancel(true);super.onStop();}
 @Override protected void onDestroy(){poll.shutdownNow();commands.shutdownNow();super.onDestroy();}
 void submit(Runnable r){try{commands.execute(r);}catch(RejectedExecutionException e){message("Bitte kurz warten");}}
 void message(String text){ui.post(()->state.setText(text));}
 Server identify(String host,int port)throws Exception{JSONObject j=request(new Server("","",host,port),"/discover","GET",null,false);if(!"DiscordDeck/1".equals(j.optString("protocol")))throw new IOException("Unbekannter Server");return new Server(j.getString("id"),j.getString("name"),host,port);}
 void found(Server server){ui.post(()->{servers.put(server.id,server);String previous=selected==null?pairedId:selected.id;ArrayList<Server> items=new ArrayList<>(servers.values());ArrayAdapter<Server> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,items);computers.setAdapter(adapter);for(int i=0;i<items.size();i++)if(items.get(i).id.equals(previous))computers.setSelection(i);if(server.id.equals(pairedId)){selected=server;pair.setVisibility(View.GONE);}else if(pairedId.isEmpty())message("PC gefunden. Einmal mit Code koppeln.");});}
 void discover(){try(DatagramSocket socket=new DatagramSocket()){socket.setBroadcast(true);socket.setSoTimeout(450);byte[] data="DISCOVER_DISCORDDECK_1".getBytes(StandardCharsets.UTF_8);socket.send(new DatagramPacket(data,data.length,InetAddress.getByName("255.255.255.255"),47837));for(int i=0;i<8;i++){byte[] b=new byte[2048];DatagramPacket response=new DatagramPacket(b,b.length);try{socket.receive(response);}catch(SocketTimeoutException e){break;}JSONObject j=new JSONObject(new String(response.getData(),0,response.getLength(),StandardCharsets.UTF_8));if("DiscordDeck/1".equals(j.optString("protocol")))found(new Server(j.getString("id"),j.getString("name"),response.getAddress().getHostAddress(),j.getInt("port")));}}catch(Exception ignored){}}
 void tick(){if(Thread.currentThread().isInterrupted())return;try{if(ticks++%3==0)discover();Server s=selected;if(s==null||!s.id.equals(pairedId)||key.isEmpty())return;Server verified=identify(s.host,s.port);if(!verified.id.equals(pairedId))throw new IOException("Anderer PC unter dieser IP");JSONObject j=request(s,"/status","GET",null,true);JSONArray slots=j.getJSONArray("slots");ui.post(()->{state.setText("Verbunden · "+s.name);for(int i=0;i<100;i++){JSONObject slot=slots.optJSONObject(i);boolean assigned=slot!=null&&slot.optBoolean("assigned");pads[i].setText(label(i,slot==null?"Frei":slot.optString("name")));pads[i].setContentDescription((i+1)+" "+(slot==null?"Frei":slot.optString("name")));pads[i].setEnabled(assigned);gains[i].setEnabled(assigned);if(!adjusting[i])gains[i].setProgress(slot==null?65:slot.optInt("volumePercent",65));pads[i].setAlpha(assigned?1f:.4f);}});}catch(Exception e){message("Verbindung verloren · suche PC erneut …");ui.post(()->{for(Button b:pads)b.setEnabled(false);for(SeekBar bar:gains)bar.setEnabled(false);});}}
 void pairDialog(){Server s=selected;if(s==null){message("Noch kein PC gefunden");return;}EditText code=new EditText(this);code.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);code.setHint("6-stelliger Code vom PC");new AlertDialog.Builder(this).setTitle("Am PC: Handy verbinden").setView(code).setNegativeButton("Abbrechen",null).setPositiveButton("Koppeln",(d,w)->{String pin=code.getText().toString().trim();if(!pin.matches("[0-9]{6}")){message("Sechs Ziffern eingeben");return;}submit(()->{try{JSONObject j=request(s,"/pair","POST",new JSONObject().put("pin",pin).toString(),false);key=j.getString("key");pairedId=j.getString("id");prefs.edit().putString("key",key).putString("id",pairedId).apply();message("Gekoppelt · Verbindung wird hergestellt");ui.post(()->pair.setVisibility(View.GONE));}catch(Exception e){message("Kopplung fehlgeschlagen. Am PC einen neuen Code anzeigen.");}});}).show();}
 void command(String path){Server s=selected;if(s==null||!s.id.equals(pairedId)){message("PC zuerst koppeln");return;}submit(()->{try{JSONObject j=request(s,path,"POST",null,true);if(!j.optBoolean("ok"))throw new IOException(j.optString("error","Befehl fehlgeschlagen"));}catch(Exception e){message(e.getMessage());}});}
 JSONObject request(Server s,String path,String method,String body,boolean auth)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("http://"+s.host+":"+s.port+path).openConnection();try{c.setConnectTimeout(1200);c.setReadTimeout(3000);c.setRequestMethod(method);if(auth)c.setRequestProperty("X-DiscordDeck-Key",key);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");try(OutputStream out=c.getOutputStream()){out.write(body.getBytes(StandardCharsets.UTF_8));}}if(c.getResponseCode()!=200)throw new IOException("PC antwortet mit "+c.getResponseCode());try(InputStream in=c.getInputStream();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){bytes.write(b,0,n);if(bytes.size()>200000)throw new IOException("Antwort zu gross");}return new JSONObject(bytes.toString("UTF-8"));}}finally{c.disconnect();}}
}
